import {
  ButtonContext,
  CalendarCell,
  CalendarGrid,
  CalendarGridBody,
  CalendarGridHeader,
  CalendarHeaderCell,
  CalendarHeading,
  CalendarMonthPicker,
  CalendarYearPicker,
  RangeCalendar as AriaRangeCalendar,
  useSlottedContext,
} from "react-aria-components";
import type {
  DateValue,
  RangeCalendarProps as AriaRangeCalendarProps,
} from "react-aria-components";
import { ChevronLeft, ChevronRight } from "./icons";
import type { ReactNode, Ref } from "react";
import { Button } from "./Button";
import { Select, SelectItem } from "./Select";
import "./RangeCalendar.css";

/**
 * Month-nav button — see `Calendar.tsx` for the full rationale. Short version: React Aria
 * puts a **localized** accessible name on the `previous`/`next` slot context
 * (`useRangeCalendar` → `stringFormatter.format(…)`), and a hardcoded `aria-label` would
 * win `mergeProps` and pin every locale to English. `isIconOnly` still demands the name at
 * compile time (component-contract §2), so it is read from the context and re-passed; the
 * literals are the no-context fallback only.
 */
function RangeCalendarNavButton({
  slot,
  children,
}: {
  slot: "previous" | "next";
  children: ReactNode;
}) {
  const context = useSlottedContext(ButtonContext, slot);
  return (
    <Button
      variant="ghost"
      size="medium"
      isIconOnly
      slot={slot}
      className="sd-range-calendar__navigation"
      aria-label={
        context?.["aria-label"] ?? (slot === "previous" ? "Previous" : "Next")
      }
    >
      {children}
    </Button>
  );
}

export interface RangeCalendarProps
  extends Omit<AriaRangeCalendarProps<DateValue>, "className" | "children"> {
  /**
   * Header navigation treatment.
   *
   * @default "buttons"
   */
  navigation?: "buttons" | "dropdown";
  /** Additional class. sd-range-calendar is always preserved. */
  className?: string;
  /** Forwarded to the root range calendar DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function RangeCalendar({
  navigation = "buttons",
  className,
  ref,
  ...props
}: RangeCalendarProps) {
  return (
    <AriaRangeCalendar
      {...props}
      ref={ref}
      className={className ? `sd-range-calendar ${className}` : "sd-range-calendar"}
    >
      {/* div, not <header>: a <header> is an implicit `banner` landmark, which is
          page-scoped — a calendar's own month-nav must not register as a page banner
          (axe landmark-banner-is-top-level). Class unchanged. */}
      <div className="sd-range-calendar__header">
        <RangeCalendarNavButton slot="previous">
          <ChevronLeft aria-hidden size="1em" />
        </RangeCalendarNavButton>
        {navigation === "dropdown" ? (
          <div className="sd-range-calendar__picker-group">
            {/* Month/year pickers reuse the DS Select (see Calendar for the value→selectedKey /
                onChange→onSelectionChange / items mapping). Registry dependency. */}
            <CalendarMonthPicker format="long">
              {({ items, value, onChange, "aria-label": ariaLabel }) => (
                <Select
                  aria-label={ariaLabel}
                  size="medium"
                  selectedKey={value}
                  onSelectionChange={onChange}
                  isDisabled={props.isDisabled}
                  items={items}
                >
                  {(item) => (
                    <SelectItem id={(item as { id: number }).id}>
                      {(item as { formatted: string }).formatted}
                    </SelectItem>
                  )}
                </Select>
              )}
            </CalendarMonthPicker>
            <CalendarYearPicker>
              {({ items, value, onChange, "aria-label": ariaLabel }) => (
                <Select
                  aria-label={ariaLabel}
                  size="medium"
                  selectedKey={value}
                  onSelectionChange={onChange}
                  isDisabled={props.isDisabled}
                  items={items}
                >
                  {(item) => (
                    <SelectItem id={(item as { id: number }).id}>
                      {(item as { formatted: string }).formatted}
                    </SelectItem>
                  )}
                </Select>
              )}
            </CalendarYearPicker>
          </div>
        ) : (
          <CalendarHeading className="sd-range-calendar__heading sd-type-title-medium" />
        )}
        <RangeCalendarNavButton slot="next">
          <ChevronRight aria-hidden size="1em" />
        </RangeCalendarNavButton>
      </div>
      <CalendarGrid className="sd-range-calendar__grid" weekdayStyle="short">
        <CalendarGridHeader>
          {(day) => (
            <CalendarHeaderCell className="sd-range-calendar__weekday sd-type-label-medium">
              {day}
            </CalendarHeaderCell>
          )}
        </CalendarGridHeader>
        <CalendarGridBody>
          {(date) => (
            <CalendarCell
              date={date}
              className="sd-range-calendar__cell sd-type-body-medium"
            />
          )}
        </CalendarGridBody>
      </CalendarGrid>
    </AriaRangeCalendar>
  );
}

.sd-range-calendar {
  display: inline-flex;
  flex-direction: column;
  gap: var(--sd-range-calendar-gap);
  width: max-content;
  color: var(--sd-range-calendar-foreground);
}

.sd-range-calendar__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sd-range-calendar-header-gap);
}

.sd-range-calendar__navigation:dir(rtl) {
  scale: -1 1;
}

.sd-range-calendar__heading {
  color: var(--sd-range-calendar-heading-foreground);
}

/* Month/year pickers are DS Select instances; their look is owned by Select. The group only
   lays them out side by side. */
.sd-range-calendar__picker-group {
  display: flex;
  align-items: center;
  gap: var(--sd-range-calendar-picker-group-gap);
}

.sd-range-calendar__grid {
  border-spacing: var(--sd-range-calendar-grid-border-spacing);
  /* Keep the grid at its intrinsic 7 × cell-size, centred under whatever the header needs.
     Without this the table is a stretched flex item: `navigation="dropdown"` makes the header
     (two Selects + both nav buttons) wider than the grid, `width: max-content` on the root
     hands that width to every child, and an auto-layout table absorbs it by widening its
     COLUMNS — but the day cells are fixed-size divs inside those columns, so they stay
     left-packed while the centred weekday headers drift right (measured: root 324.78, columns
     46.39, cells still 40). The column/day misalignment was the visible symptom, and a range
     fill is broken into a dashed line by the same gap. */
  align-self: center;
}

.sd-range-calendar__weekday {
  width: var(--sd-range-calendar-cell-size);
  height: var(--sd-range-calendar-weekday-height);
  color: var(--sd-range-calendar-weekday-foreground);
  text-align: center;
}

.sd-range-calendar__cell {
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--sd-range-calendar-cell-size);
  height: var(--sd-range-calendar-cell-size);
  color: var(--sd-range-calendar-cell-foreground);
  border-radius: var(--sd-range-calendar-cell-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  /* The wash each state lays over the cell: the surface wash, or on a selected day's fill the one
     named for its ink, which goes away from that ink (contrast-contract.mjs § the state layer). */
  --sd-range-calendar-cell-state-hover-current: var(--sd-state-hover);
  --sd-range-calendar-cell-state-pressed-current: var(--sd-state-pressed);
  text-align: center;
  cursor: pointer;
  outline: none;
}

.sd-range-calendar__cell::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-range-calendar__cell[data-hovered]::after {
  background: var(--sd-range-calendar-cell-state-hover-current);
}
.sd-range-calendar__cell[data-pressed]::after {
  background: var(--sd-range-calendar-cell-state-pressed-current);
}

.sd-range-calendar__cell[data-selected] {
  background: var(--sd-range-calendar-cell-background-selected);
  color: var(--sd-range-calendar-cell-foreground-selected);
  --sd-range-calendar-cell-state-hover-current: var(--sd-state-hover-on-accent);
  --sd-range-calendar-cell-state-pressed-current: var(--sd-state-pressed-on-accent);
  border-radius: 0;
}

.sd-range-calendar__cell[data-selection-start] {
  border-start-start-radius: var(--sd-range-calendar-cell-radius);
  corner-start-start-shape: superellipse(var(--sd-radius-curve));
  border-end-start-radius: var(--sd-range-calendar-cell-radius);
  corner-end-start-shape: superellipse(var(--sd-radius-curve));
}

.sd-range-calendar__cell[data-selection-end] {
  border-start-end-radius: var(--sd-range-calendar-cell-radius);
  corner-start-end-shape: superellipse(var(--sd-radius-curve));
  border-end-end-radius: var(--sd-range-calendar-cell-radius);
  corner-end-end-shape: superellipse(var(--sd-radius-curve));
}

.sd-range-calendar__cell[data-today] {
  box-shadow: inset 0 0 0 var(--sd-range-calendar-cell-border-width-today) var(--sd-range-calendar-cell-border-today);
}

.sd-range-calendar__cell[data-selected][data-today] {
  box-shadow: inset 0 0 0 var(--sd-range-calendar-cell-border-width-today) var(--sd-range-calendar-cell-border-selected-today);
}

/* React Aria disables a day outside the shown month (it never takes hover or press), so this ink is
   a disabled one and owes no contrast under the wash; the selector says so. */
.sd-range-calendar__cell[data-outside-month][data-disabled] {
  color: var(--sd-range-calendar-cell-foreground-outside-month);
}

.sd-range-calendar__cell[data-unavailable],
.sd-range-calendar__cell[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-range-calendar__cell[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-range-calendar__cell[data-today][data-focus-visible] {
  /* today keeps its inset under focus. If this and the plain focus rule were both (0,2,0) with the
     focus rule later, a focused TODAY would lose its marker entirely. */
  box-shadow:
    inset 0 0 0 var(--sd-range-calendar-cell-border-width-today) var(--sd-range-calendar-cell-border-today),
    0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-range-calendar__cell[data-selected][data-today][data-focus-visible] {
  /* the only combination that draws the SELECTED today inset. Keyed on
     `[data-selected][data-focus-visible]` alone, every selected focused date would wear a today
     marker whether or not it was today. A selected non-today
     cell wants the plain ring, which the base focus rule gives it, so no rule for that case. */
  box-shadow:
    inset 0 0 0 var(--sd-range-calendar-cell-border-width-today) var(--sd-range-calendar-cell-border-selected-today),
    0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
